-- Lessons of the Claude Code, MCP & Integration course, and which of its 17 questions belong to which lesson.
-- Run this once if you ran 0012 and 0013 before the course's lesson list was known (0012 and 0013 now include it for a new
-- database). Safe to re-run: lessons are added only if missing, a lesson an admin picked is never overwritten, and the
-- memberships are added only while the course has none, so a membership an admin removed is not restored.
-- Generated by scripts/generate-submodule-seed-sql.ts. Needs 0012 and 0013 to have run.

-- 1. One topic row per lesson, under every domain row of the course (5 lessons)
with lesson(course, lesson, ord, url) as (values
  ($q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$, 1, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$),
  ($q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$, 2, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$),
  ($q$Claude Code, MCP & Integration$q$, $q$Packaging Workflows$q$, 3, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$),
  ($q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$, 4, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$),
  ($q$Claude Code, MCP & Integration$q$, $q$Enterprise Integration$q$, 5, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$)
)
insert into quiz_skilljar_topics (submodule_id, course_title, lesson_title, url, order_index)
select sm.id, l.course, l.lesson, l.url, l.ord + 1
from lesson l
join quiz_submodules sm on sm.title = l.course
where not exists (select 1 from quiz_skilljar_topics t where t.submodule_id = sm.id and t.lesson_title = l.lesson);

-- 2. Point each question at its lesson (for the link under its explanation outside a module quiz); only fills empty ones
with ptr(track, domain, question, course, lesson) as (values
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer wants Claude Code to execute shell commands without prompting for approval on every step during a trusted local build. Which setting applies?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code proposes a large refactor across dozens of files. Before accepting, what should the developer review?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code is about to commit changes that include a file named .env containing database credentials. What should happen?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Where should a team store persistent project-specific instructions that Claude Code will read at the start of every session?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$What does the /compact slash command do in Claude Code?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer resumes a Claude Code session the following morning. What context is automatically available?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$During a long implementation task, a developer wants Claude Code to track which sub-tasks are done and which remain. What built-in capability supports this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A team wants Claude Code to follow a specific multi-step deployment procedure consistently. How should they package this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Packaging Workflows$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A team wants a linter to run automatically after every file edit Claude Code makes. Which mechanism enables this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Packaging Workflows$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer wants Claude Code to query an internal Jira instance during coding sessions. What is the recommended approach?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$What three primitive types can an MCP server expose to a client?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A developer wants to expose a live database query as an MCP capability. Should it be a resource or a tool?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$An MCP server exposes sensitive internal APIs. A tool call arrives with a bearer token. Where must authorisation be enforced?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A team wants to expose an internal knowledge base via MCP. Which component must the MCP server implement to be compatible with Claude Code and other MCP clients?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$An MCP server will run as a local subprocess alongside Claude Code. Which transport type is appropriate?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code's IDE extension for VS Code allows developers to do what that the terminal CLI alone does not?$q$, $q$Claude Code, MCP & Integration$q$, $q$Enterprise Integration$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A CI pipeline needs Claude Code to run non-interactively, applying a code transformation and exiting. Which flag enables this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Enterprise Integration$q$)
)
update quiz_questions qq
set topic_id = t.id
from ptr p
join quiz_modules m on m.title = p.domain and m.track = p.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = p.course
join quiz_skilljar_topics t on t.submodule_id = sm.id and t.lesson_title = p.lesson
where qq.module_id = m.id and qq.question = p.question and qq.submodule_id = sm.id and qq.topic_id is null;

-- 3. Lesson memberships for the module quiz, only while the course has none
with mem(track, domain, question, course, lesson) as (values
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer wants Claude Code to execute shell commands without prompting for approval on every step during a trusted local build. Which setting applies?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code proposes a large refactor across dozens of files. Before accepting, what should the developer review?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code is about to commit changes that include a file named .env containing database credentials. What should happen?$q$, $q$Claude Code, MCP & Integration$q$, $q$Permission Modes & Human Gates$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Where should a team store persistent project-specific instructions that Claude Code will read at the start of every session?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$What does the /compact slash command do in Claude Code?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer resumes a Claude Code session the following morning. What context is automatically available?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$During a long implementation task, a developer wants Claude Code to track which sub-tasks are done and which remain. What built-in capability supports this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Durable Project Context$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A team wants Claude Code to follow a specific multi-step deployment procedure consistently. How should they package this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Packaging Workflows$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A team wants a linter to run automatically after every file edit Claude Code makes. Which mechanism enables this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Packaging Workflows$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A developer wants Claude Code to query an internal Jira instance during coding sessions. What is the recommended approach?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$What three primitive types can an MCP server expose to a client?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A developer wants to expose a live database query as an MCP capability. Should it be a resource or a tool?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$An MCP server exposes sensitive internal APIs. A tool call arrives with a bearer token. Where must authorisation be enforced?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$A team wants to expose an internal knowledge base via MCP. Which component must the MCP server implement to be compatible with Claude Code and other MCP clients?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$An MCP server will run as a local subprocess alongside Claude Code. Which transport type is appropriate?$q$, $q$Claude Code, MCP & Integration$q$, $q$MCP Servers$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code's IDE extension for VS Code allows developers to do what that the terminal CLI alone does not?$q$, $q$Claude Code, MCP & Integration$q$, $q$Enterprise Integration$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$A CI pipeline needs Claude Code to run non-interactively, applying a code transformation and exiting. Which flag enables this?$q$, $q$Claude Code, MCP & Integration$q$, $q$Enterprise Integration$q$)
)
insert into quiz_lesson_questions (topic_id, question_id)
select (select min(t.id) from quiz_skilljar_topics t where t.course_title = mem.course and t.lesson_title = mem.lesson), qq.id
from mem
join quiz_modules m on m.title = mem.domain and m.track = mem.track
join quiz_questions qq on qq.module_id = m.id and qq.question = mem.question
where not exists (
  select 1 from quiz_lesson_questions lq join quiz_skilljar_topics tt on tt.id = lq.topic_id where tt.course_title = $q$Claude Code, MCP & Integration$q$
)
on conflict (topic_id, question_id) do nothing;

-- Check: expect 17 questions in all, every lesson with at least 2
select t.lesson_title as lesson, count(lq.id) as questions
from quiz_skilljar_topics t
left join quiz_lesson_questions lq on lq.topic_id = t.id
where t.course_title = $q$Claude Code, MCP & Integration$q$ and t.lesson_title is not null
  and t.id = (select min(t2.id) from quiz_skilljar_topics t2 where t2.course_title = t.course_title and t2.lesson_title = t.lesson_title)
group by t.lesson_title, t.order_index
order by min(t.order_index);
